#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Error {
    Malformed,
    Version,
    Range,
    Unsupported,
    Exhausted,
    Checksum,
    FirmwareStatus(FirmwareStatus),
    Quarantined,
    Backend,
    Unavailable,
    State,
    Timeout,
    ClockRegressed,
    ClockStopped,
    /// Which validation step rejected the input. A local diagnostic tag, not a
    /// wire status and never a hardware result.
    Step(&'static str),
}
pub type Result<T> = core::result::Result<T, Error>;

/// NV status codes we can name. Anything else keeps its number, so an unknown
/// firmware failure is still actionable from a log line.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct FirmwareStatus(pub u32);

impl FirmwareStatus {
    fn name(self) -> &'static str {
        match self.0 {
            raw::NV_ERR_GENERIC => "GENERIC",
            raw::NV_ERR_INVALID_OPERATION => "INVALID_OPERATION",
            raw::NV_ERR_INSUFFICIENT_RESOURCES => "INSUFFICIENT_RESOURCES",
            raw::NV_ERR_INVALID_ARGUMENT => "INVALID_ARGUMENT",
            raw::NV_ERR_INVALID_CLIENT => "INVALID_CLIENT",
            raw::NV_ERR_INVALID_OBJECT => "INVALID_OBJECT",
            raw::NV_ERR_INVALID_OBJECT_HANDLE => "INVALID_OBJECT_HANDLE",
            raw::NV_ERR_INVALID_OBJECT_PARENT => "INVALID_OBJECT_PARENT",
            raw::NV_ERR_INVALID_OWNER => "INVALID_OWNER",
            raw::NV_ERR_INVALID_PARAMETER => "INVALID_PARAMETER",
            raw::NV_ERR_INVALID_STATE => "INVALID_STATE",
            raw::NV_ERR_NO_MEMORY => "NO_MEMORY",
            raw::NV_ERR_NOT_READY => "NOT_READY",
            raw::NV_ERR_NOT_SUPPORTED => "NOT_SUPPORTED",
            raw::NV_ERR_OBJECT_NOT_FOUND => "OBJECT_NOT_FOUND",
            raw::NV_ERR_TIMEOUT => "TIMEOUT",
            raw::NV_ERR_INVALID_FUNCTION => "INVALID_FUNCTION",
            raw::NV_ERR_INVALID_OFFSET => "INVALID_OFFSET",
            raw::NV_ERR_INVALID_CLASS => "INVALID_CLASS",
            raw::NV_ERR_INSUFFICIENT_PERMISSIONS => "INSUFFICIENT_PERMISSIONS",
            _ => "UNKNOWN",
        }
    }
}

impl core::fmt::Debug for FirmwareStatus {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "{}({:#x})", self.name(), self.0)
    }
}
